WITH cleaned AS (SELECT id, customer_id, store_id, amount, discount, shipping_fee + amount AS amount_with_shipping, COALESCE(channel, 'N/A') AS channel_filled FROM orders WHERE order_date >= DATE '2023-08-06' AND channel IS DISTINCT FROM 'web') SELECT id, customer_id, SUM(discount) OVER (PARTITION BY store_id ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount, LAST_VALUE(discount, TRUE) OVER w_part AS last_known_discount FROM cleaned WINDOW w_part AS (PARTITION BY customer_id, store_id ORDER BY amount_with_shipping, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
